```ts
class TreeNode { value: number; left?: TreeNode; right?: TreeNode; }

class InOrderIterator {
  private stack: TreeNode[] = [];
  constructor(root?: TreeNode) { this.pushLeft(root); }
  private pushLeft(node?: TreeNode) {
    while (node) { this.stack.push(node); node = node.left; }
  }
  hasNext(): boolean { return this.stack.length > 0; }
  next(): number {
    const node = this.stack.pop()!;
    this.pushLeft(node.right);
    return node.value;
  }
}

const it = new InOrderIterator(treeRoot);
while (it.hasNext()) {
  console.log(it.next());   // values in sorted order, no recursion in the caller
}
```

The caller never touches `left`/`right` pointers — it only ever calls `hasNext()`/`next()`, while the iterator itself manages an explicit stack to do the in-order recursion internally, one step at a time.
